/*
 * Startup splash for the Amiga build.
 *
 * Shown in a borderless window on the default public screen (Workbench) from
 * the start of main() until the first game viewport opens, i.e. for the whole
 * appInit/package/Entry/map loading phase.  It uses only Intuition and
 * cybergraphics, never SDL or a GL library, so it is identical for every
 * renderer (MiniGL, OpenGL/OGLES, SoftDrv) and cannot disturb their contexts.
 *
 * Image data: AmigaSplashData.h, generated by tools/splash/make-amiga-splash.py.
 * Requires an RTG (15-bit or deeper) public screen; otherwise it is skipped.
 * Passing -NOSPLASH on the command line disables it.
 */
#include <string.h>

#include <exec/types.h>
#include <intuition/intuition.h>
#include <intuition/screens.h>
#include <cybergraphx/cybergraphics.h>
#include <proto/exec.h>
/* Private library bases: SDL and the MiniGL window code open/close their own. */
#define INTUITION_BASE_NAME SplashIntuitionBase
static struct IntuitionBase* SplashIntuitionBase = NULL;
#include <proto/intuition.h>
#define CYBERGFX_BASE_NAME SplashCyberGfxBase
static struct Library* SplashCyberGfxBase = NULL;
#include <proto/cybergraphics.h>

#include "AmigaSplashData.h"

void AmigaDebugLogf( const char* Fmt, ... );

static struct Window* SplashWindow = NULL;

static void SplashCloseLibraries( void )
{
    if( SplashCyberGfxBase )
        CloseLibrary( SplashCyberGfxBase );
    if( SplashIntuitionBase )
        CloseLibrary( (struct Library*)SplashIntuitionBase );
    SplashCyberGfxBase = NULL;
    SplashIntuitionBase = NULL;
}

void AmigaSplashOpen( int argc, const char** argv )
{
    struct Screen* Scr;
    LONG Left, Top;
    int i;

    if( SplashWindow )
        return;
    for( i = 1; i < argc; ++i )
        if( argv[i] && ( strcmp( argv[i], "-NOSPLASH" ) == 0 || strcmp( argv[i], "-nosplash" ) == 0 ) )
            return;

    SplashIntuitionBase = (struct IntuitionBase*)OpenLibrary( "intuition.library", 39 );
    SplashCyberGfxBase = OpenLibrary( "cybergraphics.library", 41 );
    if( !SplashIntuitionBase || !SplashCyberGfxBase )
    {
        AmigaDebugLogf( "[Amiga] Splash: intuition/cybergraphics not available" );
        SplashCloseLibraries();
        return;
    }

    Scr = LockPubScreen( NULL );
    if( !Scr )
    {
        SplashCloseLibraries();
        return;
    }
    if( !GetCyberMapAttr( Scr->RastPort.BitMap, CYBRMATTR_ISCYBERGFX )
        || GetCyberMapAttr( Scr->RastPort.BitMap, CYBRMATTR_DEPTH ) < 15 )
    {
        AmigaDebugLogf( "[Amiga] Splash: public screen is not a 15+ bit RTG screen, skipped" );
        UnlockPubScreen( NULL, Scr );
        SplashCloseLibraries();
        return;
    }

    Left = ( Scr->Width - AMIGA_SPLASH_WIDTH ) / 2;
    Top = ( Scr->Height - AMIGA_SPLASH_HEIGHT ) / 2;
    if( Left < 0 ) Left = 0;
    if( Top < 0 ) Top = 0;

    SplashWindow = OpenWindowTags( NULL,
        WA_PubScreen, (ULONG)Scr,
        WA_Left, Left,
        WA_Top, Top,
        WA_Width, AMIGA_SPLASH_WIDTH,
        WA_Height, AMIGA_SPLASH_HEIGHT,
        WA_Borderless, TRUE,
        WA_SmartRefresh, TRUE,
        WA_Activate, FALSE,
        WA_RMBTrap, TRUE,
        WA_IDCMP, 0,
        WA_Title, (ULONG)"Unreal",
        TAG_DONE );
    UnlockPubScreen( NULL, Scr );

    if( !SplashWindow )
    {
        AmigaDebugLogf( "[Amiga] Splash: OpenWindowTags failed" );
        SplashCloseLibraries();
        return;
    }

    WriteLUTPixelArray( (APTR)AmigaSplashPixels, 0, 0, AMIGA_SPLASH_WIDTH,
        SplashWindow->RPort, (APTR)AmigaSplashPalette,
        0, 0, AMIGA_SPLASH_WIDTH, AMIGA_SPLASH_HEIGHT, CTABFMT_XRGB8 );
    AmigaDebugLogf( "[Amiga] Splash: shown at %ld,%ld", (long)Left, (long)Top );
}

void AmigaSplashClose( void )
{
    if( SplashWindow )
    {
        CloseWindow( SplashWindow );
        SplashWindow = NULL;
        AmigaDebugLogf( "[Amiga] Splash: closed" );
    }
    SplashCloseLibraries();
}
